# Generated by Antigravity AI Agent (Google)

import serial
import serial.tools.list_ports
import time
import csv
import argparse
import os
import json


def find_arduino():
    """Auto-detect connected Arduino Mega/Uno serial port, skipping Digilent AD2."""
    for port in serial.tools.list_ports.comports():
        desc = (port.description or "").lower()
        dev = port.device.lower()
        if "digilent" in desc or "digilent" in dev:
            continue
        if getattr(port, "vid", None) == 0x2341 or "arduino" in desc or "usbmodem" in dev or "usbserial" in dev:
            return port.device
    return None


def open_serial_connection(port=None, timeout=1):
    """Safely open the Arduino serial connection."""
    target_port = port or find_arduino()
    if not target_port:
        return None
    try:
        ser = serial.Serial(target_port, 115200, timeout=timeout)
        time.sleep(1.5)  # Allow DTR reset to settle
        ser.reset_input_buffer()
        return ser
    except Exception:
        return None


def generate_html(csv_file="rpm_data.csv", html_file="rpm_graph.html"):
    """Generate an interactive Chart.js HTML graph from the CSV log."""
    times, rpms = [], []
    last_valid_time = None

    try:
        with open(csv_file, "r") as f:
            reader = csv.reader(f)
            next(reader, None)  # Skip header
            for row in reader:
                if len(row) >= 5:
                    try:
                        t_val = float(row[0])
                        r_val = float(row[2])
                        if r_val > 30000.0:
                            r_val = 0.0

                        # Detect gap (> 1.0s) between samples
                        if last_valid_time is not None and (t_val - last_valid_time > 1.0):
                            times.extend([round(last_valid_time + 0.1, 2), round(t_val - 0.1, 2)])
                            rpms.extend([None, None])

                        times.append(t_val)
                        rpms.append(r_val)
                        last_valid_time = t_val
                    except (ValueError, IndexError):
                        pass
    except FileNotFoundError:
        return

    valid_rpms = [r for r in rpms if r is not None]
    latest_rpm = valid_rpms[-1] if valid_rpms else 0.0
    peak_rpm = max(valid_rpms) if valid_rpms else 0.0
    total_pts = len(valid_rpms)
    y_max = max(3000, int((peak_rpm * 1.15) / 1000) * 1000 + 1000) if peak_rpm > 0 else 3000

    html_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>Live Propeller Speed Graph</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <meta http-equiv="refresh" content="2">
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; text-align: center; background-color: #f8fafc; color: #1e293b; margin: 0; padding: 20px;">
    <h2>Live Propeller Speed Data</h2>
    <p style="font-size: 1.1em;">
        <strong>Latest Speed:</strong> <span style="color: #2563eb;">{latest_rpm:.1f} RPM</span> &bull;
        <strong>Peak:</strong> <span style="color: #16a34a;">{peak_rpm:.1f} RPM</span> &bull;
        <strong>Total Logged:</strong> {total_pts} samples
    </p>
    <div style="width: 90%; max-width: 1200px; margin: auto; background: white; padding: 24px; border-radius: 12px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1);">
        <canvas id="rpmChart"></canvas>
    </div>
    <script>
        const ctx = document.getElementById('rpmChart').getContext('2d');
        new Chart(ctx, {{
            type: 'line',
            data: {{
                labels: {json.dumps(times)},
                datasets: [{{
                    label: 'Propeller Speed (RPM)',
                    data: {json.dumps(rpms)},
                    borderColor: '#2563eb',
                    backgroundColor: 'rgba(37, 99, 235, 0.12)',
                    borderWidth: 2,
                    pointRadius: {1 if total_pts > 100 else 2},
                    spanGaps: false,
                    tension: 0.1,
                    fill: true
                }}]
            }},
            options: {{
                responsive: true,
                animation: false,
                scales: {{
                    x: {{ title: {{ display: true, text: 'Time (seconds)', font: {{ weight: 'bold' }} }}, grid: {{ color: 'rgba(0,0,0,0.05)' }} }},
                    y: {{ title: {{ display: true, text: 'Speed (RPM)', font: {{ weight: 'bold' }} }}, min: 0, suggestedMax: {y_max}, grid: {{ color: 'rgba(0,0,0,0.05)' }} }}
                }}
            }}
        }});
    </script>
</body>
</html>"""

    with open(html_file, "w") as f:
        f.write(html_content)


def main():
    parser = argparse.ArgumentParser(description="Log Arduino Propeller Speed Data")
    parser.add_argument("-p", "--port", type=str, help="Specify serial port (default: auto-detect)")
    parser.add_argument("-a", "--append", action="store_true", help="Resume/append to existing rpm_data.csv")
    args = parser.parse_args()

    csv_file = "rpm_data.csv"
    html_file = "rpm_graph.html"
    sample_counter = 0

    if not (args.append and os.path.exists(csv_file)):
        with open(csv_file, "w", newline="") as f:
            f.write("Time_s,Sample,RPM,Frequency_Hz,Period_us\n")

    print(f"\nConnecting to Arduino... (Logging to {csv_file} | Press Ctrl+C to stop)")

    ser = None
    last_html_update = time.time()
    try:
        while True:
            if ser is None or not getattr(ser, "is_open", False):
                ser = open_serial_connection(args.port)
                if ser is None:
                    time.sleep(1.0)
                    continue
                print(f"Connected to Arduino on {ser.port}.")
                last_html_update = time.time()

            try:
                if ser.in_waiting > 0:
                    line = ser.readline().decode("utf-8", errors="replace").strip()
                    if not line:
                        continue
                    if line.startswith("#"):
                        print(line)
                        continue

                    parts = line.split(",")
                    if len(parts) >= 5 and parts[0].replace(".", "", 1).isdigit():
                        time_s, _, rpm, freq, period = parts[:5]
                        sample_counter += 1

                        with open(csv_file, "a", newline="") as f:
                            f.write(f"{time_s},{sample_counter},{rpm},{freq},{period}\n")

                        print(f"[Sample #{sample_counter:>4d} | Time: {time_s:>6s}s] Speed: {float(rpm):6.1f} RPM ({float(freq):5.1f} Hz)")

                        if time.time() - last_html_update >= 1.0:
                            generate_html(csv_file, html_file)
                            last_html_update = time.time()
                else:
                    time.sleep(0.02)
            except Exception:
                if ser:
                    ser.close()
                ser = None
                time.sleep(1.0)

    except KeyboardInterrupt:
        print("\nStopping logger.")
    finally:
        generate_html(csv_file, html_file)
        if ser and getattr(ser, "is_open", False):
            ser.close()


if __name__ == "__main__":
    main()
